const items = Array.from({ length: 20 }, (_, i) => `Documento ${i + 1}`);
<ScrollArea maxHeight="314px" scrollbarGap="lg" aria-label="Documentos recientes">
  <ul>
    {items.map((item) => (
      <li key={item}>{item}</li>
    ))}
  </ul>
</ScrollArea>

const photos = Array.from({ length: 12 }, (_, i) => `Foto ${i + 1}`);
<ScrollArea orientation="horizontal" scrollbarGap="lg" aria-label="Galería de fotos">
  <ul className="flex w-max gap-2">
    {photos.map((photo) => (
      <li key={photo}>{photo}</li>
    ))}
  </ul>
</ScrollArea>
